{
  "name": "Удаление пользователя по ID",
  "event": [
    {
      "listen": "test",
      "script": {
        "exec": [
          "const userId = pm.collectionVariables.get(\"userid\");",
          "const statusCode = pm.response.code;",
          "const responseText = pm.response.text();",
          "",
          "console.log(\"=== УДАЛЕНИЕ ПОЛЬЗОВАТЕЛЯ ===\");",
          "console.log(\"User ID:\", userId);",
          "console.log(\"Статус:\", statusCode);",
          "console.log(\"Ответ:\", responseText);",
          "",
          "pm.test(\"Время ответа < 2000ms\", () => {",
          "    pm.expect(pm.response.responseTime).to.be.below(2000);",
          "});",
          "",
          "if (statusCode === 200) {",
          "    console.log(\"✅ Пользователь удалён\");",
          "    pm.test(\"Статус 200 - успешное удаление\", () => true);",
          "    pm.collectionVariables.unset(\"userid\");",
          "    pm.collectionVariables.unset(\"username\");",
          "    console.log(\"🧹 Переменные пользователя очищены\");",
          "} else if (statusCode === 404) {",
          "    console.log(\"⚠️ Пользователь уже был удалён или не существует\");",
          "    pm.test(\"404 - пользователь не найден\", () => true);",
          "} else {",
          "    console.log(\"❌ Неожиданный статус:\", statusCode);",
          "    pm.test(`Ожидался 200 или 404, получен ${statusCode}`, () => false);",
          "}"
        ]
      }
    }
  ],
  "request": {
    "method": "DELETE",
    "auth": {
      "type": "bearer",
      "bearer": [
        {
          "key": "token",
          "value": "{{master-key}}",
          "type": "string"
        }
      ]
    },
    "url": {
      "raw": "{{base_url}}/users/{{userid}}",
      "host": ["{{base_url}}"],
      "path": ["users", "{{userid}}"]
    }
  }
}
